@startuml

class Song {
  + title : string
  + year : int
  + length : int
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteURL : string
}

class User {
  + userID : int
  + name : string
  + address : string
}

class RegularUser {}

class BusinessUser {
  + VATNumber : string
}

class Single {}

class Hit {}

class Album {
  + title : string
}

class Purchase {
  + purchaseDate : date
}

class Suggestion {
  + similarityScore : double
}

Song --|> Single
Song --|> Hit

Artist "1" -- "*" Song
User "1" -- "*" Single : buys
User "1" -- "*" Album : composes
User "1" -- "*" Purchase
User "1" -- "*" Suggestion

BusinessUser "1" -- "*" Song : uploads
Single "*" -- "1" RegularUser
Hit "*" -- "1" Album
Album "1" -- "1..*" Hit
Hit "1" -- "1" Album : trackNumber

RegularUser --|> User
BusinessUser --|> User

@enduml

